553	  document.querySelectorAll('.card').forEach(function (card) {
554	    var svg = card.querySelector('.stage svg');
555	    if (!svg) return;
556	    var name = (card.querySelector('.name') || {}).textContent || 'asset';
557	
558	    // Replay control on the stage — re-runs the asset's animation for inspection.
559	    var stage = card.querySelector('.stage');
560	    if (stage) {
561	      var replay = document.createElement('button');
562	      replay.type = 'button';
563	      replay.className = 'replay-btn';
564	      replay.innerHTML = REPLAY_IC + '<span>Replay</span>';
565	      replay.setAttribute('aria-label', 'Replay the ' + name + ' animation');
566	      replay.addEventListener('click', function () { replayAnimations(svg); });
567	      stage.appendChild(replay);
568	    }
569	
570	    var btn = document.createElement('button');
571	    btn.type = 'button';
572	    btn.className = 'copy-btn';
573	    btn.innerHTML = COPY_IC + '<span>Copy SVG</span>';
574	    btn.setAttribute('aria-label', 'Copy SVG markup for ' + name);
575	
576	    btn.addEventListener('click', function () {
577	      var markup = buildSvg(svg);
578	      var done = function () {
579	        btn.classList.add('done');
580	        btn.innerHTML = DONE_IC + '<span>Copied!</span>';
581	        showToast('SVG copied — paste it anywhere');
582	        setTimeout(function () {
583	          btn.classList.remove('done');
584	          btn.innerHTML = COPY_IC + '<span>Copy SVG</span>';
585	        }, 1800);
586	      };
587	      if (navigator.clipboard && navigator.clipboard.writeText) {
588	        navigator.clipboard.writeText(markup).then(done, function () {
589	          if (fallbackCopy(markup)) done(); else showToast('Copy failed — select manually');
590	        });
591	      } else {
592	        if (fallbackCopy(markup)) done(); else showToast('Copy failed — select manually');
593	      }
594	    });
595	
596	    var dl = document.createElement('button');
597	    dl.type = 'button';
598	    dl.className = 'dl-btn';
599	    dl.innerHTML = DL_IC;
600	    dl.setAttribute('aria-label', 'Download ' + name + ' as an SVG file');
601	    dl.title = 'Download .svg';
602	    dl.addEventListener('click', function () {
603	      downloadSvg(buildSvg(svg), slugify(name) + '.svg');
604	      showToast('Downloaded ' + slugify(name) + '.svg');
605	    });
606	
607	    var actions = document.createElement('div');
608	    actions.className = 'actions';
609	    actions.appendChild(btn);
610	    actions.appendChild(dl);
611	    card.querySelector('.body').appendChild(actions);
612	  });
613	
614	  // ---- Journey-stage filtering ----
615	  var cards = Array.prototype.slice.call(document.querySelectorAll('.card'));
616	  var chips = Array.prototype.slice.call(document.querySelectorAll('.filterbar .chip'));
617	  var countEl = document.getElementById('fbCount');
618	  var emptyNote = document.getElementById('emptyNote');
619	
620	  function applyFilter(filter) {
621	    var shown = 0;
622	    cards.forEach(function (card) {
623	      var match = filter === 'all' || card.getAttribute('data-cat') === filter;
624	      card.classList.toggle('hide', !match);
625	      if (match) shown++;
626	    });
627	    chips.forEach(function (chip) {
628	      chip.setAttribute('aria-pressed', String(chip.getAttribute('data-filter') === filter));
629	    });
630	    countEl.textContent = shown + (shown === 1 ? ' asset' : ' assets');
631	    emptyNote.style.display = shown === 0 ? 'block' : 'none';
632	  }
633	
634	  chips.forEach(function (chip) {
635	    chip.addEventListener('click', function () { applyFilter(chip.getAttribute('data-filter')); });
636	  });
637	
638	  // ---- Global motion toggle (freeze/resume all asset animations) ----
639	  var motionBtn = document.getElementById('motionToggle');
640	  if (motionBtn) {
641	    motionBtn.addEventListener('click', function () {
642	      var paused = document.body.classList.toggle('motion-paused');
643	      motionBtn.setAttribute('aria-pressed', String(paused));
644	      motionBtn.setAttribute('aria-label', paused ? 'Resume all asset animations' : 'Pause all asset animations');
645	    });
646	  }
647	
648	  // ---- Dark-stage preview toggle (flip every stage to a dark product surface) ----
649	  var stageBtn = document.getElementById('stageToggle');
650	  if (stageBtn) {
651	    stageBtn.addEventListener('click', function () {
652	      var dark = document.body.classList.toggle('stage-dark');
653	      stageBtn.setAttribute('aria-pressed', String(dark));
654	      stageBtn.setAttribute('aria-label', dark ? 'Preview assets on a light surface' : 'Preview assets on a dark surface');
655	    });
656	  }
657	})();
658	</script>
659	</body>
